"""wordstats: a tiny word-count utility used as a benchmark seed fixture."""
"""Word-count utilities for the wordstats mock project."""


def count_words(text):
    """Return a mapping of lowercased words to occurrence counts.

    Punctuation is stripped from token edges; tokens that are only
    punctuation are ignored.
    """
    counts = {}
    for raw in text.lower().split():
        word = raw.strip(".,;:!?-\"'()")
        if word:
            counts[word] = counts.get(word, 0) + 1
    return counts
"""Focused unit tests for wordstats.counter."""

import unittest

from wordstats.counter import count_words


class CountWordsTests(unittest.TestCase):
    def test_counts_basic_words(self):
        self.assertEqual(count_words("apple banana apple"), {"apple": 2, "banana": 1})

    def test_strips_punctuation_and_lowercases(self):
        self.assertEqual(count_words("Apple! apple, BANANA."), {"apple": 2, "banana": 1})

    def test_ignores_punctuation_only_tokens(self):
        self.assertEqual(count_words("-- ..."), {})

    def test_empty_input(self):
        self.assertEqual(count_words(""), {})


if __name__ == "__main__":
    unittest.main()
